import{_ as t,o as d,c as e,Q as o}from"./chunks/framework.48927342.js";const k=JSON.parse('{"title":"动词人称变位","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/grammar/03-person-conjugation.md","filePath":"zh/more/maltese/grammar/03-person-conjugation.md"}'),c={name:"zh/more/maltese/grammar/03-person-conjugation.md"},a=o('<h1 id="动词人称变位" tabindex="-1">动词人称变位 <a class="header-anchor" href="#动词人称变位" aria-label="Permalink to &quot;动词人称变位&quot;">​</a></h1><h2 id="_1-人称标记与变位公式" tabindex="-1">1. 人称标记与变位公式 <a class="header-anchor" href="#_1-人称标记与变位公式" aria-label="Permalink to &quot;1. 人称标记与变位公式&quot;">​</a></h2><p>马耳他语动词根据主语的人称和单复数改变形式。代词通常可以省略，因为动词形式往往已经标出人称；需要强调或对比时再说出代词。<code>hu</code>（他）和 <code>hi</code>（她）区分第三人称单数的阳性/阴性，<code>inti</code>（你，单数）对男女都可使用。</p><p>常见形式可概括为“人称前缀 + 动词词干”：第一人称常见 <code>n-</code>，第二人称常见 <code>t-</code>，第三人称阳性常见 <code>j-</code>；第三人称阴性常与第二人称单数同形。复数常用复数词干或 <code>-u</code> 词尾。以 <code>kiteb</code>（写）为例：</p><table><thead><tr><th>人称</th><th>代词</th><th>常见标记</th><th><code>kiteb</code> 的形式</th></tr></thead><tbody><tr><td>第一人称单数</td><td>jien</td><td>n-</td><td>nikteb</td></tr><tr><td>第二人称单数</td><td>inti</td><td>t-</td><td>tikteb</td></tr><tr><td>第三人称单数阳性</td><td>hu</td><td>j-</td><td>jikteb</td></tr><tr><td>第三人称单数阴性</td><td>hi</td><td>t-</td><td>tikteb</td></tr><tr><td>第一人称复数</td><td>aħna</td><td>n- + 复数词干</td><td>niktbu</td></tr><tr><td>第二人称复数</td><td>intom</td><td>t- + 复数词干</td><td>tiktbu</td></tr><tr><td>第三人称复数</td><td>huma</td><td>j- + 复数词干</td><td>jiktbu</td></tr></tbody></table><p>这是常见模板，不是对所有动词都适用的机械公式；词根类型和词干变化需要逐词记忆。</p><h3 id="għ-的位置与词干变化" tabindex="-1"><code>għ</code> 的位置与词干变化 <a class="header-anchor" href="#għ-的位置与词干变化" aria-label="Permalink to &quot;`għ` 的位置与词干变化&quot;">​</a></h3><ul><li>词根以 <code>għ</code> 开头时，人称前缀接入后，<code>għ</code> 通常仍保留在拼写中，但词干元音可能变化，例如 <code>għen</code> → <code>ngħin</code>、<code>għex</code> → <code>ngħix</code>。</li><li>词根中间含 <code>għ</code> 时，<code>għ</code> 通常保留在拼写中，前后元音或词干可能变化，例如 <code>bagħat</code> → <code>nibgħat</code>、<code>qagħad</code> → <code>noqgħod</code>、<code>biegħ</code> → <code>nbiegħ</code>。</li><li>因而可以记为“人称前缀 + 对应词干模板”；<code>għ</code> 词没有适用于所有词根的字符替换公式，应按具体动词记忆。</li></ul><h2 id="_2-15-个目标动词的完整人称变位" tabindex="-1">2. 15 个目标动词的完整人称变位 <a class="header-anchor" href="#_2-15-个目标动词的完整人称变位" aria-label="Permalink to &quot;2. 15 个目标动词的完整人称变位&quot;">​</a></h2><p>下表依次列出 5 个常用动词、5 个词首含 <code>għ</code> 的动词，以及 5 个词中含 <code>għ</code> 的动词。词义分列中文、英文和马耳他语；七个人称也各占一列。这里只展示人称形式，不展开时态讲解。</p><table><thead><tr><th>中文</th><th>English</th><th>Malti</th><th>jien（我）</th><th>inti（你，单数）</th><th>hu（他）</th><th>hi（她）</th><th>aħna（我们）</th><th>intom（你们）</th><th>huma（他们/她们）</th></tr></thead><tbody><tr><td>吃</td><td>eat</td><td>kiel</td><td><code>niekol</code></td><td><code>tiekol</code></td><td><code>jiekol</code></td><td><code>tiekol</code></td><td><code>nieklu</code></td><td><code>tieklu</code></td><td><code>jieklu</code></td></tr><tr><td>喝</td><td>drink</td><td>xorob</td><td><code>nixrob</code></td><td><code>tixrob</code></td><td><code>jixrob</code></td><td><code>tixrob</code></td><td><code>nixorbu</code></td><td><code>tixorbu</code></td><td><code>jixorbu</code></td></tr><tr><td>去</td><td>go</td><td>mar</td><td><code>mmur</code></td><td><code>tmur</code></td><td><code>jmur</code></td><td><code>tmur</code></td><td><code>mmorru</code></td><td><code>tmorru</code></td><td><code>jmorru</code></td></tr><tr><td>写</td><td>write</td><td>kiteb</td><td><code>nikteb</code></td><td><code>tikteb</code></td><td><code>jikteb</code></td><td><code>tikteb</code></td><td><code>niktbu</code></td><td><code>tiktbu</code></td><td><code>jiktbu</code></td></tr><tr><td>读</td><td>read</td><td>qara</td><td><code>naqra</code></td><td><code>taqra</code></td><td><code>jaqra</code></td><td><code>taqra</code></td><td><code>naqraw</code></td><td><code>taqraw</code></td><td><code>jaqraw</code></td></tr><tr><td>做</td><td>make/do</td><td>għamel</td><td><code>nagħmel</code></td><td><code>tagħmel</code></td><td><code>jagħmel</code></td><td><code>tagħmel</code></td><td><code>nagħmlu</code></td><td><code>tagħmlu</code></td><td><code>jagħmlu</code></td></tr><tr><td>帮助</td><td>help</td><td>għen</td><td><code>ngħin</code></td><td><code>tgħin</code></td><td><code>jgħin</code></td><td><code>tgħin</code></td><td><code>ngħinu</code></td><td><code>tgħinu</code></td><td><code>jgħinu</code></td></tr><tr><td>生活/居住</td><td>live</td><td>għex</td><td><code>ngħix</code></td><td><code>tgħix</code></td><td><code>jgħix</code></td><td><code>tgħix</code></td><td><code>ngħixu</code></td><td><code>tgħixu</code></td><td><code>jgħixu</code></td></tr><tr><td>关闭</td><td>close</td><td>għalaq</td><td><code>nagħlaq</code></td><td><code>tagħlaq</code></td><td><code>jagħlaq</code></td><td><code>tagħlaq</code></td><td><code>nagħlqu</code></td><td><code>tagħlqu</code></td><td><code>jagħlqu</code></td></tr><tr><td>选择</td><td>choose</td><td>għażel</td><td><code>nagħżel</code></td><td><code>tagħżel</code></td><td><code>jagħżel</code></td><td><code>tagħżel</code></td><td><code>nagħżlu</code></td><td><code>tagħżlu</code></td><td><code>jagħżlu</code></td></tr><tr><td>发送</td><td>send</td><td>bagħat</td><td><code>nibgħat</code></td><td><code>tibgħat</code></td><td><code>jibgħat</code></td><td><code>tibgħat</code></td><td><code>nibagħtu</code></td><td><code>tibagħtu</code></td><td><code>jibagħtu</code></td></tr><tr><td>停留/居住</td><td>stay</td><td>qagħad</td><td><code>noqgħod</code></td><td><code>toqgħod</code></td><td><code>joqgħod</code></td><td><code>toqgħod</code></td><td><code>noqogħdu</code></td><td><code>toqogħdu</code></td><td><code>joqogħdu</code></td></tr><tr><td>出售</td><td>sell</td><td>biegħ</td><td><code>nbigħ</code></td><td><code>tbigħ</code></td><td><code>jbigħ</code></td><td><code>tbigħ</code></td><td><code>nbigħu</code></td><td><code>tbigħu</code></td><td><code>jbigħu</code></td></tr><tr><td>点亮/打开（灯）</td><td>switch on</td><td>xegħel</td><td><code>nixgħel</code></td><td><code>tixgħel</code></td><td><code>jixgħel</code></td><td><code>tixgħel</code></td><td><code>nixegħlu</code></td><td><code>tixegħlu</code></td><td><code>jixegħlu</code></td></tr><tr><td>感到惊讶</td><td>be surprised</td><td>stagħġeb</td><td><code>nistagħġeb</code></td><td><code>tistagħġeb</code></td><td><code>jistagħġeb</code></td><td><code>tistagħġeb</code></td><td><code>nistagħġbu</code></td><td><code>tistagħġbu</code></td><td><code>jistagħġbu</code></td></tr></tbody></table><h3 id="三语例句" tabindex="-1">三语例句 <a class="header-anchor" href="#三语例句" aria-label="Permalink to &quot;三语例句&quot;">​</a></h3><p>每个动词选用一个人称造句，例句按中文、英文和马耳他语分列。</p><table><thead><tr><th>动词</th><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>kiel</td><td>我们吃面包。</td><td>We eat bread.</td><td>Aħna nieklu l-ħobż.</td></tr><tr><td>xorob</td><td>她喝水。</td><td>She drinks water.</td><td>Hi tixrob l-ilma.</td></tr><tr><td>mar</td><td>你回家。</td><td>You go home.</td><td>Inti tmur id-dar.</td></tr><tr><td>kiteb</td><td>他们写一封信。</td><td>They write a letter.</td><td>Huma jiktbu ittra.</td></tr><tr><td>qara</td><td>他读一本书。</td><td>He reads a book.</td><td>Hu jaqra ktieb.</td></tr><tr><td>għamel</td><td>我做晚餐。</td><td>I make dinner.</td><td>Jien nagħmel l-ikla ta&#39; filgħaxija.</td></tr><tr><td>għen</td><td>你帮助一位朋友。</td><td>You help a friend.</td><td>Inti tgħin lil ħabib.</td></tr><tr><td>għex</td><td>他们住在马耳他。</td><td>They live in Malta.</td><td>Huma jgħixu f&#39;Malta.</td></tr><tr><td>għalaq</td><td>她关上门。</td><td>She closes the door.</td><td>Hi tagħlaq il-bieb.</td></tr><tr><td>għażel</td><td>我们选一本书。</td><td>We choose a book.</td><td>Aħna nagħżlu ktieb.</td></tr><tr><td>bagħat</td><td>我发送一条消息。</td><td>I send a message.</td><td>Jien nibgħat messaġġ.</td></tr><tr><td>qagħad</td><td>他待在家里。</td><td>He stays at home.</td><td>Hu joqgħod id-dar.</td></tr><tr><td>biegħ</td><td>你卖书。</td><td>You sell books.</td><td>Inti tbigħ kotba.</td></tr><tr><td>xegħel</td><td>我们打开灯。</td><td>We switch on the light.</td><td>Aħna nixegħlu d-dawl.</td></tr><tr><td>stagħġeb</td><td>他们感到惊讶。</td><td>They are surprised.</td><td>Huma jistagħġbu.</td></tr></tbody></table><p>表达身份时，马耳他语通常不单独使用系词“是”，例如 <code>Jien student.</code>（我是学生。）</p><h2 id="_3-性别与一致" tabindex="-1">3. 性别与一致 <a class="header-anchor" href="#_3-性别与一致" aria-label="Permalink to &quot;3. 性别与一致&quot;">​</a></h2><ul><li><code>hu</code> 和 <code>hi</code> 区分阳性、阴性；第三人称动词也可能区分性别，如 <code>jikteb</code>（他写）与 <code>tikteb</code>（她写）。</li><li>第二人称单数 <code>inti</code> 对男女都可用，动词形式在上述例子中相同。</li><li>名词和形容词可能发生性数一致：<code>tifel tajjeb</code>（好男孩）、<code>tifla tajba</code>（好女孩）。</li><li>复数的人称动词常使用特定词尾，但不要把一个动词的变位直接推广到所有词根。</li></ul><h2 id="_4-练习模板" tabindex="-1">4. 练习模板 <a class="header-anchor" href="#_4-练习模板" aria-label="Permalink to &quot;4. 练习模板&quot;">​</a></h2><p>把动词替换进下面的句型，再改变主语：</p><ul><li><code>Jien ___ il-ħobż.</code>：我……面包。</li><li><code>Hi ___ l-ilma.</code>：她……水。</li><li><code>Aħna ___ id-dar.</code>：我们……回家/在家。</li></ul><p>动词形式和例句应一起记忆；遇到不规则或借词动词，优先查完整变位表。</p><h2 id="_5-参考词条" tabindex="-1">5. 参考词条 <a class="header-anchor" href="#_5-参考词条" aria-label="Permalink to &quot;5. 参考词条&quot;">​</a></h2><ul><li><a href="https://en.wiktionary.org/wiki/g%C4%A7amel#Maltese" target="_blank" rel="noreferrer">Wiktionary：għamel</a></li><li><a href="https://en.wiktionary.org/wiki/qag%C4%A7ad#Maltese" target="_blank" rel="noreferrer">Wiktionary：qagħad</a></li><li><a href="https://en.wiktionary.org/wiki/bag%C4%A7at#Maltese" target="_blank" rel="noreferrer">Wiktionary：bagħat</a></li><li><a href="https://en.wiktionary.org/wiki/g%C4%A7en#Maltese" target="_blank" rel="noreferrer">Wiktionary：għen</a></li></ul>',23),i=[a];function r(l,n,g,h,b,u){return d(),e("div",null,i)}const m=t(c,[["render",r]]);export{k as __pageData,m as default};
